window.RP_SESSION={"id":"S-6f32e499dde9","messages":[{"id":"RP-III-0046843","time":"2026-03-15T19:04:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하하하!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046844","time":"2026-03-15T19:04:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"맥주!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046845","time":"2026-03-15T19:05:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"라르손은 리엔이가져온 닭고기를 양파와 이것저것을넣고 양념하여 모닥불에서 꼬치에꼽아 굽고있습니다.","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046846","time":"2026-03-15T19:05:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"지글지글~","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046847","time":"2026-03-15T19:07:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"슬금슬금 피어오르는 냄새에 이끌려 살금살금 다가갑니다.\n\n\"라르손 씨, 그거 꼬치인가요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046848","time":"2026-03-15T19:07:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"물론일세, 양념된 닭꼬치라네!\"\n\n닭꼬치와... 맥주!","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046849","time":"2026-03-15T19:08:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 나도 낄래~ \"\n\n닭꼬치... 처음 모험을 나서서는 쳐다도 보지 않았던 음식이지만 이제는 없어서 못먹는 바로 그 음식.\n\n맛있는 닭 지방이 타는 냄새에 잭 또한 자연스럽게 착석합니다.\n\n\" 좋은 맥주를 좀 구해왔거든. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046850","time":"2026-03-15T19:09:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"좋구먼, 맥주는 많을수록좋지~!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046851","time":"2026-03-15T19:09:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"하아~ 양념이던 뭐던 맥주만 있다면야\"\n\n\"큼, ....그랴도 오늘은 한잔만 마시죠.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046852","time":"2026-03-15T19:10:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하하, 짠~!\"\n\n향기가풍부한 에일을 한잔씩들 따라주면서~","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046853","time":"2026-03-15T19:11:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 그런 말이 있잖아~ \"\n\n라그손이 따라준 맥주를 쭉 원샷한다.\n\n\" 어... 까먹었다. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046854","time":"2026-03-15T19:11:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"맥주면 충분하다네!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046855","time":"2026-03-15T19:12:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"으음 물론이요. 맥주 정도면 딱 충분하죠\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046856","time":"2026-03-15T19:13:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 아, 그래! 혹시 바바리안 브류라고 들어봤어? \"\n\n잭은 새 맥주를 받으며 이야기를 꺼냅니다.\n\n\" 바바리안들이 맥주를 먹는 방식인데... 맛이 죽여준대. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046857","time":"2026-03-15T19:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"맥주 마시는 방법도 뭐 따로있어요? 참..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046858","time":"2026-03-15T19:14:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"나는 드워프식으로 마시는맥주를 가장~ 좋아한다네!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046859","time":"2026-03-15T19:15:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 내가 기억하기로는... 바바리안 브류라는게... \"\n\n잭은 곰곰히 기억을 되새겨서 레시피를 생각해냅니다.\n\n\" 그날 사냥으로 잡은걸 전부 차갑게 식혀서 맥주에 넣어서 먹는걸거야. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046860","time":"2026-03-15T19:16:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"고기는 뜨거울때 따로뜯고, 맥주는 따로먹어야 맛있지!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046861","time":"2026-03-15T19:16:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"일단 마시면 되지 않나요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046862","time":"2026-03-15T19:17:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 그래. 건배 할까? \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046863","time":"2026-03-15T19:17:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"짠~\"\n\n건배~!","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046864","time":"2026-03-15T19:18:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 잭 해리슨의 성공적인 사랑을 위해서~! \"\n\n건배사를 멋대로 가져가버립니다.","characters":["P-58df75b248fb"]},{"id":"RP-III-0046865","time":"2026-03-15T19:19:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046866","time":"2026-03-15T19:19:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하하, 위하여~!\"\n\n알빠아닙니다. 맥주최고!","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046867","time":"2026-03-15T19:19:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"......ㅁ뭐죠 저 건배사...?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046868","time":"2026-03-15T19:20:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 응? 건배사지. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046869","time":"2026-03-15T19:21:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"꿀떡꿀떡","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046870","time":"2026-03-15T19:21:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"크으~ 맛있구먼!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046871","time":"2026-03-15T19:21:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...예..;\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046872","time":"2026-03-15T19:23:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 어우... 아 그래... 닭꼬치 좀 먹어도 돼? \"\n\n꼬치가 먹고 싶어서 합류한 잭이지만 종일 술만 마시고 있었습니다.","characters":["P-58df75b248fb"]},{"id":"RP-III-0046873","time":"2026-03-15T19:28:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"얼마든지먹게! 으하하!\"\n\n냠냠꿀꺽","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046874","time":"2026-03-15T19:28:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"먹고마시고~","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046875","time":"2026-03-15T19:29:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"예이~\"\n\n꼬치 하나 집어들어 고기 빼먹습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046876","time":"2026-03-15T19:30:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 야호~ 오늘은 뱃살 걱정 없이 먹어야지. \"\n\n닭꼬치를 잡고 뜯기 시작합니다.","characters":["P-58df75b248fb"]},{"id":"RP-III-0046877","time":"2026-03-15T19:30:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 아... 뱃살 나오면 머챈트가 싫어하려나...? \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046878","time":"2026-03-15T19:31:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하, 신경쓰지말게~! 오늘은 즐기는날일세!\"","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046879","time":"2026-03-15T19:33:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"에이 원래... 뭐냐 살 빼다가도 하루쯤은 쉬어줘야죠~\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046880","time":"2026-03-15T19:34:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 원래 그런거야? 난 쉬다가 하루 빼고 그러는데. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046881","time":"2026-03-15T19:35:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하, 나는 안뺀다네!\"\n\n꿀꺽꿀꺽","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046882","time":"2026-03-15T19:35:00+09:00","room":"RP III","name":"라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"뇸뇸","characters":["P-b551ad21c43a"]},{"id":"RP-III-0046883","time":"2026-03-15T19:35:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 그래보여. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046884","time":"2026-03-15T19:36:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"당연히 그러시면 안빠지죠!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046885","time":"2026-03-15T19:41:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 그치만 빼는건 귀찮잖아! \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046886","time":"2026-03-15T19:41:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"어쩌겠어요!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046888","time":"2026-03-15T20:13:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 오늘은 그냥 마실래 그럼~ \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046889","time":"2026-03-15T20:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"그게 맘 편하긴 하죠\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0046890","time":"2026-03-15T20:23:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"' 바스락- '\n\n\" 아, 역시 누가 있었네요. \"\n\n 길드 주변을 산책하다가 캠프장에서 피어오르는 연기에 이끌리듯 캠프장으로 온 조바입니다.\n\n 가볍게 목례를 하곤, 자연스럽게 자리에 착석합니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0046891","time":"2026-03-15T20:26:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 오? 새로운 친구가 하나 합류했네. \"\n\n자연스럽게 앉은 하일로의 앞으로 맥주를 한잔 따라서 건네준다.\n\n\" 마셔. 환영주야. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046892","time":"2026-03-15T20:26:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"바스락바스락","characters":[]},{"id":"RP-III-0046893","time":"2026-03-15T20:26:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"...걍 바스락거리기만 한다.","characters":[]},{"id":"RP-III-0046894","time":"2026-03-15T20:30:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" ..? 아, 예예.. \"\n\n 자연스럽게 그가 건네준 맥주를 한 모금 마십니다.\n\n\" 크- 그나저나, 새로 오신 분인가요? \"","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0046895","time":"2026-03-15T20:32:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 나? 그런 셈이지 뭐~ \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046896","time":"2026-03-15T20:34:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 그렇군요.. \"\n\n 잔에 남아있는 맥주를 한 모금 마신 후, 그에게 자신을 소개합니다.\n\n\" 하일로 조바입니다. 그쪽은 이름이? \"","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0046897","time":"2026-03-15T20:35:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 잭 해리슨이야. \"\n\n먼저 오른손을 내밀어서 악수를 청한다.","characters":["P-58df75b248fb"]},{"id":"RP-III-0046898","time":"2026-03-15T20:37:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 예, 기억하겠습니다. \"\n\n 그의 악수를 받으며 살짝 웃는 조바.","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0046899","time":"2026-03-15T20:43:00+09:00","room":"RP III","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 좋아. 너도 닭꼬치나 먹어. \"","characters":["P-58df75b248fb"]},{"id":"RP-III-0046900","time":"2026-03-16T06:46:00+09:00","room":"RP III","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f6ccefd2c259"]},{"id":"RP-III-0046901","time":"2026-03-16T06:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
